INSERT INTO op_user (
	USER_NO
	, USER_ID
	, PASSWORD
	, AREA_CODE
	, AREA_SE_CODE_S
	, AREA_SE_CODE_D
	, USER_NM
	, CTTPC_SE_CODE
	, CTTPC
	, EMAIL
	, USER_STTUS_CODE
	, MEMBER_CODE
	, BRANCH_ID
	, REGISTER_NO
	, REGIST_DT
) VALUES (
	  #{user_no}
	, #{user_id}
	, #{enPwd}
	, #{area_se_code_m}
	, #{area_se_code_s}
	, #{area_se_code_d}
	, #{user_nm}
	, #{cttpc_se_code}
	, #{cttpc}
	, #{email}
	, #{user_sttus_code}
	, #{author_id}
	, #{branch_id}
	, #{ss_user_no}
	, CURRENT_TIMESTAMP
)

